CREATE TABLE r1_report_definitions(tenant_id TEXT NOT NULL,id TEXT NOT NULL,dataset_id TEXT NOT NULL,org_id TEXT NOT NULL,title TEXT NOT NULL,draft TEXT NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,published_version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id));
CREATE TABLE r1_report_definition_versions(tenant_id TEXT NOT NULL,definition_id TEXT NOT NULL,version INTEGER NOT NULL,digest TEXT NOT NULL,payload TEXT NOT NULL,published_by TEXT NOT NULL,published_at TEXT NOT NULL,PRIMARY KEY(tenant_id,definition_id,version));
CREATE TRIGGER r1_report_definition_immutable_update BEFORE UPDATE ON r1_report_definition_versions BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REPORT_DEFINITION'); END;
CREATE TRIGGER r1_report_definition_immutable_delete BEFORE DELETE ON r1_report_definition_versions BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REPORT_DEFINITION'); END;
CREATE TABLE r1_report_generations(tenant_id TEXT NOT NULL,id TEXT NOT NULL,dataset_id TEXT NOT NULL,definition_version TEXT NOT NULL,producer_version TEXT NOT NULL,source_manifest TEXT NOT NULL,source_cutoff INTEGER NOT NULL,scope_org TEXT NOT NULL,status TEXT NOT NULL,build_cursor TEXT NOT NULL,revision INTEGER NOT NULL,row_count INTEGER NOT NULL,content_digest TEXT,created_by TEXT NOT NULL,generated_at TEXT NOT NULL,completed_at TEXT,PRIMARY KEY(tenant_id,id));
CREATE INDEX r1_report_latest_generation ON r1_report_generations(tenant_id,dataset_id,status,completed_at DESC,id);
CREATE TABLE r1_report_rows(tenant_id TEXT NOT NULL,dataset_id TEXT NOT NULL,generation_id TEXT NOT NULL,row_key TEXT NOT NULL,org_id TEXT NOT NULL,person_id TEXT,policy_kind TEXT NOT NULL,policy_key TEXT NOT NULL,event_date TEXT,currency TEXT,cells TEXT NOT NULL,source_version TEXT NOT NULL,key_parts TEXT NOT NULL,PRIMARY KEY(tenant_id,dataset_id,generation_id,row_key));
CREATE INDEX r1_report_row_scope ON r1_report_rows(tenant_id,dataset_id,generation_id,org_id,row_key);
CREATE INDEX r1_report_row_person ON r1_report_rows(tenant_id,dataset_id,generation_id,person_id,row_key);
CREATE INDEX r1_report_row_date ON r1_report_rows(tenant_id,dataset_id,generation_id,event_date,row_key);
CREATE TRIGGER r1_report_rows_immutable_update BEFORE UPDATE ON r1_report_rows BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REPORT_ROW'); END;
CREATE TRIGGER r1_report_rows_immutable_delete BEFORE DELETE ON r1_report_rows BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REPORT_ROW'); END;
CREATE TABLE r1_report_chunks(tenant_id TEXT NOT NULL,generation_id TEXT NOT NULL,sequence INTEGER NOT NULL,first_key TEXT NOT NULL,last_key TEXT NOT NULL,row_count INTEGER NOT NULL,byte_count INTEGER NOT NULL,digest TEXT NOT NULL,PRIMARY KEY(tenant_id,generation_id,sequence));
CREATE TABLE r1_report_snapshots(tenant_id TEXT NOT NULL,id TEXT NOT NULL,dataset_id TEXT NOT NULL,generation_id TEXT NOT NULL,definition_version TEXT NOT NULL,business_cutoff TEXT NOT NULL,generated_at TEXT NOT NULL,source_manifest TEXT NOT NULL,row_key_schema TEXT NOT NULL,row_count INTEGER NOT NULL,chunk_refs TEXT NOT NULL,content_digest TEXT NOT NULL,created_by TEXT NOT NULL,purpose TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE r1_report_query_cursors(tenant_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,query_digest TEXT NOT NULL,generation_id TEXT NOT NULL,authorization_revision INTEGER NOT NULL,writer_epoch INTEGER NOT NULL,recovery_epoch INTEGER NOT NULL,last_key TEXT NOT NULL,last_sort TEXT NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX r1_m01_version_cutoff ON r1_m01_versions(tenant_id,entity_id,workspace_revision DESC,version DESC);
